import LensManager, { ILens, LensLayerName } from "#core/ui/lenses/lens-manager.js";

class DefaultLens implements ILens {
	activeLayers = new Set<LensLayerName>(["fxs-culture-borders-layer", "fxs-operation-target-layer"]);
	allowedLayers = new Set<LensLayerName>([
		"fxs-hexgrid-layer",
		"fxs-resource-layer",
		"fxs-yields-layer",
		"fxs-conquest-layer",
	]);

	/**
	 * Do not blend on transition.
	 * Users are able to manage which layers to use in the default lens, so stick with those.
	 */
	blendEnabledLayersOnTransition = false;

	useUserConfig = true;
}

declare global {
	interface LensTypeMap {
		"fxs-default-lens": DefaultLens;
	}
}

LensManager.registerLens("fxs-default-lens", new DefaultLens());
